import math

def is_square(n):
    if n < 0:
        return False
    root = int(math.isqrt(n))
    return root * root == n

def is_suitable(x):
    # Check if there exist positive integers a < b such that a*b = x and (b-a) is even
    # This is equivalent to checking if there exists a divisor d of x with d < sqrt(x) and (x/d - d) is even
    sqrt_x = int(math.isqrt(x))
    for d in range(1, sqrt_x + 1):
        if x % d == 0:
            other = x // d
            if d < other and (other - d) % 2 == 0:
                return True
    return False

def find_nth_suitable(N):
    count = 0
    x = 1
    while True:
        if is_suitable(x):
            count += 1
            if count == N:
                return x
        x += 1

N = int(input())
print(find_nth_suitable(N))
